CREATE TABLE `seat_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `session_id` varchar(50) NOT NULL,
  `cinema_id` varchar(30) NOT NULL,
  `cinema_name` varchar(200) DEFAULT NULL,
  `movie_title` varchar(200) DEFAULT NULL,
  `movie_format` varchar(20) DEFAULT NULL,
  `movie_language` varchar(50) DEFAULT NULL,
  `movie_label` varchar(10) DEFAULT NULL,
  `showtime` datetime DEFAULT NULL,
  `screen_name` varchar(50) DEFAULT NULL,
  `screen_number` int DEFAULT NULL,
  `seats_available` int DEFAULT NULL,
  `expire_time` datetime DEFAULT NULL,
  `tickets_data` json DEFAULT NULL,
  `seats_layout` json DEFAULT NULL,
  `concession_items` json DEFAULT NULL,
  `standard_price` decimal(10,2) DEFAULT NULL,
  `vip_price` decimal(10,2) DEFAULT NULL,
  `couple_price` decimal(10,2) DEFAULT NULL,
  `search_date` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=495 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
